// CSD_RATIONALE_BEGIN
// Diagnosis of primary failure modes across attempts:
//
// 1. mode_M (19 wrong, attempt 32): 17 examples produced no "<<" at all.
//    Cause: attempt 32's guidance said "Do NOT write << anywhere else", so the model
//    suppressed natural "<< >>" emission during reasoning. Then Phase 3's guard
//    "steps < maxSteps" was false (Phase 1 exhausted all 900 steps), so Phase 3
//    never ran.
//
// 2. mode_I (9 wrong, persistent): Long spans (avg 121 tokens) with malformed content
//    (repetitive arithmetic chains, `{braces}`, etc.).
//    Cause: CloseSpanWithinBudget was given the FULL remaining budget (~700 steps
//    after the model naturally emitted "<<" at ~190 tokens). The parser accepts
//    expressions like `int(a) + int(b) - int(c)...` as complete, so it tracked
//    the longest complete prefix — which grew to hundreds of tokens.
//
// Fix: cap the constrained-span budget at spanBudget=50 steps. Median valid span
// length is 11 tokens, so 50 steps is ample while preventing runaway repetition.
// Phase 1 stops at maxSteps - 51 (not maxSteps), guaranteeing Phase 3 always has
// a 51-step reserve for force-open + close.
//
// Strategy:
// Phase 1: Free unconstrained generation with RenderedEndsWith("<<") detection.
//   Runs up to maxSteps - spanBudget - 1 steps. Breaks immediately on "<<" detection
//   or EOS. The model naturally emits "<<" at median ~190 tokens.
// Phase 2: CloseSpanWithinBudget with min(50, remaining) steps. Enforces short span.
// Phase 3: Force-open "<<" with OpenConstrainedSpan (only if no span appeared),
//   then CloseSpanWithinBudget with min(50, remaining) steps.
//   Guaranteed budget: Phase 1 ≤ maxSteps-51 steps, Phase 3 = 1+50 = 51 steps,
//   total ≤ maxSteps.
//
// Guidance simplified vs attempt 32: removes the "Do NOT write << anywhere else"
// restriction that caused mode_M failures, keeps clear format rules.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1: parser_validity
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   Initialization: from precondition.
//
//   Phase 1 loop — unconstrained branch:
//     The loop guard is !insideConstrainedOut, so the antecedent is false for
//     every body execution until "<<" is detected. When RenderedEndsWith detects
//     "<<", we set currentConstrainedOut := [] and insideConstrainedOut := true.
//     parser.IsValidPrefix([]) holds by the requires clause on the method
//     (parser.IsValidPrefix([])), so the invariant is satisfied immediately.
//     The loop then exits (guard fails).
//
//   Phase 1 loop — EOS branch:
//     break fires before any assignment; insideConstrainedOut stays false,
//     antecedent remains false, invariant vacuously preserved.
//
//   Phase 2 (CloseSpanWithinBudget):
//     Postcondition directly guarantees insideOut ==> parser.IsValidPrefix(currentOut),
//     so the invariant is restored regardless of whether the span was closed or left open.
//
//   Phase 3 (OpenConstrainedSpan + CloseSpanWithinBudget):
//     OpenConstrainedSpan sets insideOut := true, currentOut := [].
//     parser.IsValidPrefix([]) holds by requires. CloseSpanWithinBudget then
//     guarantees insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2: progress
//   |generated| <= |generatedPrefix| + steps  (and steps <= maxSteps)
//
//   Initialization: |generated| = |generatedPrefix|, steps = 0; equality holds.
//
//   Phase 1 loop body (non-EOS): appends exactly one token and increments steps
//     by 1, so Δ|generated| = Δsteps = 1; invariant preserved.
//   Phase 1 loop body (EOS): steps increments by 1, generated unchanged;
//     |generated| <= |generatedPrefix| + (steps-1) < |generatedPrefix| + steps;
//     invariant preserved.
//   Entering constrained mode (RenderedEndsWith): no further append in that
//     iteration; invariant still holds on the incremented steps.
//
//   Phase 2: CloseSpanWithinBudget postcondition gives
//     |generatedOut| <= |generated| + budget2 <= |generatedPrefix| + steps_before + budget2
//     = |generatedPrefix| + steps_after (since steps := steps_before + budget2).
//     EOS or rejected suffix tokens inside CloseSpanWithinBudget count against budget2
//     without extending visible output, so visible growth ≤ budget2.
//
//   Phase 3: OpenConstrainedSpan appends 1 token (steps += 1).
//     CloseSpanWithinBudget then adds ≤ budget3 to |generated| and steps += budget3.
//     With phase1Budget = maxSteps - spanBudget - 1:
//     worst case: (maxSteps - 51) steps in Phase 1 + 1 (open) + 50 (close) = maxSteps.
//     So steps ≤ maxSteps and |generated| ≤ |generatedPrefix| + maxSteps. ✓
// CSD_PROOF_SKETCH_END

  generated := generatedPrefix;
  insideConstrainedOut := insideConstrained;
  currentConstrainedOut := currentConstrained;
  cost := 0;

  helpers.AppendTaskGuidance(lm,
    "Solve this math problem step by step. " +
    "At the very end, write your final answer exactly once as: <<int(expr)>> " +
    "Rules for expr: variable names without curly braces, integers, +, -, *, /, //, %, (, ), int(). " +
    "Always wrap in int(). No {braces}, no ** operator, no LaTeX. " +
    "Keep the expression short. Example: <<int(n * price - discount)>>");

  var spanBudget: nat := 50;
  var steps: nat := 0;
  var hadConstrainedActivity: bool := insideConstrained;

  // Phase 1: Free unconstrained generation, detect "<<" and break immediately
  if !insideConstrainedOut {
    var phase1Budget: nat;
    if maxSteps > spanBudget + 1 {
      phase1Budget := maxSteps - spanBudget - 1;
    } else {
      phase1Budget := 0;
    }

    while steps < phase1Budget && !insideConstrainedOut
      invariant 0 <= steps <= maxSteps
      invariant lm.ValidTokensIdsLogits()
      invariant !insideConstrainedOut ==> currentConstrainedOut == []
      invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
      invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
      invariant |generated| <= |generatedPrefix| + steps
      decreases phase1Budget - steps
    {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
    hadConstrainedActivity := hadConstrainedActivity || insideConstrainedOut;
  }

  // Phase 2: Close any open constrained span with capped budget
  if insideConstrainedOut && steps < maxSteps {
    var remaining2: nat := maxSteps - steps;
    var budget2: nat;
    if remaining2 < spanBudget {
      budget2 := remaining2;
    } else {
      budget2 := spanBudget;
    }
    var cg2, ci2, cc2 := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget2
    );
    generated := cg2;
    insideConstrainedOut := ci2;
    currentConstrainedOut := cc2;
    steps := steps + budget2;
  }

  // Phase 3: Force-open a constrained span if no span was ever opened
  if !hadConstrainedActivity && !insideConstrainedOut && steps < maxSteps {
    var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
    generated := og;
    insideConstrainedOut := oi;
    currentConstrainedOut := oc;
    steps := steps + 1;

    if insideConstrainedOut && steps < maxSteps {
      var remaining3: nat := maxSteps - steps;
      var budget3: nat;
      if remaining3 < spanBudget {
        budget3 := remaining3;
      } else {
        budget3 := spanBudget;
      }
      var cg3, ci3, cc3 := helpers.CloseSpanWithinBudget(
        lm, parser, prompt, generated, currentConstrainedOut, eosToken, budget3
      );
      generated := cg3;
      insideConstrainedOut := ci3;
      currentConstrainedOut := cc3;
      steps := steps + budget3;
    }
  }

  cost := steps;

